<?php $title='Portfolio';include 'includes/header.php';$rows=db()->query('SELECT * FROM projects ORDER BY project_id DESC')->fetchAll();?><section class="section"><div class="container"><p class="gold">SELECTED WORK</p><h1>Portfolio / Gallery</h1><div class="row g-4 mt-3"><?php foreach($rows as $p):?><div class="col-md-4"><div class="card overflow-hidden h-100"><?php if($p['image']):?><img src="uploads/<?=e($p['image'])?>" class="w-100" style="height:220px;object-fit:cover"><?php endif;?><div class="p-4"><span class="badge badge-gold"><?=e($p['category'])?></span><h4 class="mt-2"><?=e($p['title'])?></h4><p class="text-secondary"><?=e($p['description'])?></p><?php if($p['video_url']):?><a href="<?=e($p['video_url'])?>" target="_blank" class="gold">Watch video</a><?php endif;?></div></div></div><?php endforeach;if(!$rows):?><p class="text-secondary">Portfolio projects will appear here.</p><?php endif;?></div></div></section><?php include 'includes/footer.php';?>
